// features/auth.feature: "Signing out clears the session cookie"
// Logout is deprecated. Per the OpenAPI description, this test must stay skipped
// until the cookie rewrite ships, because a running test fails the release.
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("sign out", () => {
  test.skip("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
    // Arrange: sign in so the session cookie is set on the request context
    const login = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: PASSWORD },
    });
    await expectStatus(login, 200);

    // Act
    const response = await request.post("/api/auth/logout");

    // Assert: 204 with no body
    expect(response.status()).toBe(204);

    // Assert: the session cookie is cleared (expired or Max-Age=0)
    const setCookies = response
      .headersArray()
      .filter((h) => h.name.toLowerCase() === "set-cookie")
      .map((h) => h.value);
    const sessionCookie = setCookies.find((value) => value.startsWith("session="));
    expect(sessionCookie).toBeDefined();
    const lower = sessionCookie!.toLowerCase();
    const expired = lower.includes("max-age=0") || lower.includes("expires=thu, 01 jan 1970");
    expect(expired).toBe(true);
  });
});
